}

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => supabase ? false : sessionStorage.getItem("studytrack-auth") === "true");
  const [isAdmin, setIsAdmin] = useState(!supabase);
  const [currentUser, setCurrentUser] = useState(null);
  const [profileLoadError, setProfileLoadError] = useState("");
  const [activePage, setActivePage] = useState("dashboard");
  const [selectedTask, setSelectedTask] = useState(null);
  const [profileMenuOpen, setProfileMenuOpen] = useState(false);
  const visiblePage = !isAdmin && activePage === "admin" ? "dashboard" : activePage;
  const [, , Page] = pages.find(([key]) => key === visiblePage) || pages[0];
  const userName = currentUser?.full_name || currentUser?.email?.split("@")[0] || "Користувач";
  const userInitial = userName.slice(0, 1).toUpperCase();

  useEffect(() => {
    document.documentElement.classList.remove("dark");

    if (!supabase) return undefined;

    let mounted = true;

    const loadUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!mounted || !session) {
        if (mounted) {
          setCurrentUser(null);
          setIsAuthenticated(false);
          setIsAdmin(false);
        }
        return;
      }

      setIsAuthenticated(true);

      const { data: profile, error: profileError } = await supabase
        .from("profiles")
        .select("full_name, email, phone, university, course, group_name, avatar_url, role")
        .eq("id", session.user.id)
        .maybeSingle();
      const { data: moodleConnection } = await supabase
        .from("moodle_connections")
        .select("last_synced_at")
        .eq("user_id", session.user.id)
        .maybeSingle();

      if (profileError) setProfileLoadError(profileError.message);

      if (mounted) {
        setCurrentUser({
          id: session.user.id,
          email: profile?.email || session.user.email,
          phone: profile?.phone || "",
          university: profile?.university || "",
          course: profile?.course || "",
          group_name: profile?.group_name || "",
          full_name: profile?.full_name || session.user.user_metadata?.full_name || session.user.user_metadata?.name || "Користувач",
          avatar_url: profile?.avatar_url || session.user.user_metadata?.avatar_url || null,
          moodleConnected: Boolean(moodleConnection),
          role: profile?.role || "student",
        });
        setIsAdmin(profile?.role === "admin");
      }
    };

    loadUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      if (!session) {
        setIsAuthenticated(false);
        setIsAdmin(false);
        setCurrentUser(null);
        return;
      }

      const { data: profile, error: profileError } = await supabase
        .from("profiles")
        .select("full_name, email, phone, university, course, group_name, avatar_url, role")
        .eq("id", session.user.id)
        .maybeSingle();

      if (profileError) setProfileLoadError(profileError.message);

      const { data: moodleConnection } = await supabase
        .from("moodle_connections")
        .select("last_synced_at")
        .eq("user_id", session.user.id)
        .maybeSingle();

      setIsAuthenticated(true);
      setCurrentUser({
        id: session.user.id,
        email: profile?.email || session.user.email,
        phone: profile?.phone || "",
        university: profile?.university || "",
        course: profile?.course || "",
        group_name: profile?.group_name || "",
        full_name: profile?.full_name || session.user.user_metadata?.full_name || session.user.user_metadata?.name || "Користувач",
        avatar_url: profile?.avatar_url || session.user.user_metadata?.avatar_url || null,
        moodleConnected: Boolean(moodleConnection),
        role: profile?.role || "student",
      });
      setIsAdmin(profile?.role === "admin");
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, []);

  const openTask = (task) => setSelectedTask(task);
  const closeTask = () => setSelectedTask(null);

  const handleLogin = () => {
    sessionStorage.setItem("studytrack-auth", "true");
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    if (supabase) supabase.auth.signOut();
    sessionStorage.removeItem("studytrack-auth");
    setSelectedTask(null);
    setIsAdmin(false);
    setIsAuthenticated(false);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-[#f5f5f7] text-[#1d1d1f]">
      <SideNavigation
        activePage={visiblePage}
        isAdmin={isAdmin}
        user={currentUser}
        onNavigate={(page) => {
          closeTask();
          setActivePage(page);
          setProfileMenuOpen(false);
        }}
      />
      <main className="min-h-screen pl-72">
        {visiblePage === "dashboard" && <div className="fixed right-6 top-3 z-50">
          <button
            type="button"
            aria-label="Відкрити меню профілю"
            aria-expanded={profileMenuOpen}
            onClick={() => setProfileMenuOpen((open) => !open)}
            className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-full bg-gray-900 text-white shadow-sm transition hover:bg-gray-700 focus:outline-none focus:ring-4 focus:ring-blue-100"
          >
            {currentUser?.avatar_url ? <img src={currentUser.avatar_url} alt="Аватар користувача" className="h-full w-full object-cover" /> : <span className="text-sm font-medium">{userInitial}</span>}
          </button>
          {profileMenuOpen && (
            <div className="absolute right-0 top-12 w-60 rounded-xl border border-gray-100 bg-white p-2 text-gray-900 shadow-xl">
              <div className="flex items-center gap-3 border-b border-gray-100 px-3 pb-3 pt-2">
                {currentUser?.avatar_url ? <img src={currentUser.avatar_url} alt="Аватар користувача" className="h-9 w-9 rounded-full object-cover" /> : <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gray-900 text-sm font-medium text-white">{userInitial}</span>}
                <div className="min-w-0">
                  <p className="break-words text-sm font-semibold">{userName}</p>
                  <p className="mt-1 break-all text-xs text-gray-500">{currentUser?.email || "email@domain.com"}</p>
                </div>
              </div>
              <button type="button" onClick={() => { setActivePage("profile"); setProfileMenuOpen(false); }} className="mt-1 flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-gray-600 transition hover:bg-gray-100 hover:text-gray-900">
                <span className="material-symbols-outlined" style={{ fontSize: 18 }}>person</span>
                Профіль
              </button>
              <button type="button" onClick={() => { setActivePage("settings"); setProfileMenuOpen(false); }} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-gray-600 transition hover:bg-gray-100 hover:text-gray-900">
                <span className="material-symbols-outlined" style={{ fontSize: 18 }}>settings</span>
                Налаштування
              </button>
              <button type="button" onClick={handleLogout} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-red-600 transition hover:bg-red-50">
                <span className="material-symbols-outlined" style={{ fontSize: 18 }}>logout</span>
                Вийти
              </button>
            </div>
          )}
        </div>}
        {selectedTask ? (
          <TaskDetails task={selectedTask} onBack={closeTask} onComplete={closeTask} onTaskUpdate={setSelectedTask} />
        ) : (
          <Page
            key={currentUser?.id || "guest"}
            onNavigate={setActivePage}
            onOpenTask={openTask}
            onLogout={handleLogout}
            user={currentUser}
            onUserUpdate={setCurrentUser}
            profileLoadError={profileLoadError}
          />
        )}
      </main>
    </div>
  );
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { ...corsHeaders, "Content-Type": "application/json" },
});

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (request.method !== "POST") {
    return json({ error: "Only POST is supported" }, 405);
  }

  const authorization = request.headers.get("Authorization");
  if (!authorization) {
    return json({ error: "Authorization header is required" }, 401);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authorization } } },
  );

  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) {
    return json({ error: "Invalid session" }, 401);
  }

  const body = await request.json().catch(() => ({}));
  const { data: savedConnection } = await supabase
    .from("moodle_connections")
    .select("base_url, token")
    .eq("user_id", user.id)
    .maybeSingle();
  const moodleBaseUrl = String(body.baseUrl || savedConnection?.base_url || "").replace(/\/$/, "");
  const moodleToken = String(body.token || savedConnection?.token || "");
  if (!moodleBaseUrl || !moodleToken) return json({ error: "Moodle is not connected" }, 400);

  const callMoodle = async (wsfunction: string, params: Record<string, string | number>) => {
    const url = new URL(`${moodleBaseUrl}/webservice/rest/server.php`);
    url.searchParams.set("wstoken", moodleToken);
    url.searchParams.set("wsfunction", wsfunction);
    url.searchParams.set("moodlewsrestformat", "json");
    Object.entries(params).forEach(([key, value]) => url.searchParams.set(key, String(value)));
    const response = await fetch(url);
    const result = await response.json();
    if (!response.ok || result.exception) throw new Error(result.message ?? `Moodle request failed (${response.status})`);
    return result;
  };

  let siteInfo;
  let moodleCourses;
  let assignments = [];
  try {
    siteInfo = await callMoodle("core_webservice_get_site_info", {});
    moodleCourses = await callMoodle("core_enrol_get_users_courses", { userid: siteInfo.userid });
    const assignmentResults = await Promise.all((moodleCourses ?? []).map((course: { id: number }) =>
      callMoodle("mod_assign_get_assignments", { "courseids[0]": course.id }).catch(() => ({ courses: [] }))));
    assignments = assignmentResults.flatMap((result) => result.courses?.flatMap((course: { assignments?: unknown[] }) => course.assignments ?? []) ?? []);
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Moodle connection failed" }, 502);
  }

  const { error: saveConnectionError } = await supabase.from("moodle_connections").upsert({
    user_id: user.id,
    base_url: moodleBaseUrl,
    token: moodleToken,
    external_user_id: String(siteInfo.userid),
    last_synced_at: new Date().toISOString(),
  }, { onConflict: "user_id" });
  if (saveConnectionError) return json({ error: saveConnectionError.message }, 500);

  for (const course of moodleCourses ?? []) {
    const { error } = await supabase.from("courses").upsert({
      user_id: user.id,
      name: course.fullname ?? course.shortname ?? `Course ${course.id}`,
      color: "gray",
      source: "moodle",
      external_id: String(course.id),
    }, { onConflict: "user_id,source,external_id" });
    if (error) return json({ error: error.message }, 500);
  }

  const { data: savedCourses } = await supabase.from("courses").select("id, external_id").eq("user_id", user.id).eq("source", "moodle");
  for (const assignment of assignments as Array<{ id: number; name: string; duedate?: number; course?: number }>) {
    const course = savedCourses?.find((item) => item.external_id === String(assignment.course));
    if (!course) continue;
    await supabase.from("tasks").upsert({
      user_id: user.id,
      course_id: course.id,
      title: assignment.name,
      description: null,
      due_at: assignment.duedate ? new Date(assignment.duedate * 1000).toISOString() : null,
      source: "moodle",
      external_id: String(assignment.id),
    }, { onConflict: "user_id,source,external_id" });
  }

  return json({
    ok: true,
    userId: user.id,
    moodleBaseUrl,
    synced: true,
    courses: moodleCourses?.length ?? 0,
    assignments: assignments.length,
  });
});

create extension if not exists "pgcrypto";

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  email text,
  phone text,
  university text,
  course text,
  group_name text,
  avatar_url text,
  role text not null default 'student' check (role in ('student', 'admin')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.courses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  color text not null default 'gray',
  source text not null default 'manual' check (source in ('manual', 'moodle')),
  external_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, source, external_id)
);

create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id uuid references public.courses(id) on delete set null,
  title text not null,
  description text,
  due_at timestamptz,
  completed_at timestamptz,
  source text not null default 'manual' check (source in ('manual', 'moodle')),
  external_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, source, external_id)
);

create table public.moodle_connections (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references auth.users(id) on delete cascade,
  base_url text not null,
  external_user_id text,
  connected_at timestamptz not null default now(),
  last_synced_at timestamptz
);

create index courses_user_id_idx on public.courses(user_id);
create index tasks_user_id_idx on public.tasks(user_id);
create index tasks_due_at_idx on public.tasks(user_id, due_at);

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger profiles_set_updated_at
before update on public.profiles
for each row execute function public.set_updated_at();

create trigger courses_set_updated_at
before update on public.courses
for each row execute function public.set_updated_at();

create trigger tasks_set_updated_at
before update on public.tasks
for each row execute function public.set_updated_at();

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, avatar_url)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url'
  );
  return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.tasks enable row level security;
alter table public.moodle_connections enable row level security;

create policy "Users can read their profile"
on public.profiles for select
using (auth.uid() = id or public.is_admin());

create policy "Users can update their profile"
on public.profiles for update
using (auth.uid() = id)
with check (auth.uid() = id);

create policy "Users can manage their courses"
on public.courses for all
using (auth.uid() = user_id)
with check (auth.uid() = user_id);

create policy "Admins can read all courses"
on public.courses for select
using (public.is_admin());

create policy "Users can manage their tasks"
on public.tasks for all
using (auth.uid() = user_id)
with check (auth.uid() = user_id);

create policy "Admins can read all tasks"
on public.tasks for select
using (public.is_admin());

create policy "Users can manage their Moodle connection"
on public.moodle_connections for all
using (auth.uid() = user_id)
with check (auth.uid() = user_id);

create policy "Admins can read all Moodle connections"
on public.moodle_connections for select
using (public.is_admin());

alter table public.profiles
  add column if not exists email text,
  add column if not exists phone text,
  add column if not exists university text,
  add column if not exists course text,
  add column if not exists group_name text,
  add column if not exists role text not null default 'student';

update public.profiles
set role = 'student'
where role is null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'profiles_role_check'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_role_check check (role in ('student', 'admin'));
  end if;
end
$$;

alter table public.moodle_connections
  add column if not exists token text;

alter table public.tasks
  add column if not exists notes text,
  add column if not exists subtasks jsonb not null default '[]'::jsonb,
  add column if not exists is_important boolean not null default false;

notify pgrst, 'reload schema';

notify pgrst, 'reload schema';

do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'profiles'
      and policyname = 'Users can create their profile'
  ) then
    create policy "Users can create their profile"
    on public.profiles for insert
    with check (auth.uid() = id);
  end if;
end
$$;

