export default function CourseList({ user }) {
  const [selected, setSelected] = useState(null);
  const [filter, setFilter] = useState("");
  const [liveCourses, setLiveCourses] = useState(() => (supabase ? [] : courses));
  const [syncStatus, setSyncStatus] = useState("idle");
  const [syncError, setSyncError] = useState("");
  const [moodleModal, setMoodleModal] = useState(false);
  const [moodleUrl, setMoodleUrl] = useState("");
  const [moodleToken, setMoodleToken] = useState("");

  useEffect(() => {
    if (!supabase || !user?.id) return;
    supabase.from("courses").select("*, tasks(*)").eq("user_id", user.id).order("name")
      .then(({ data, error }) => {
        if (error) setSyncError(error.message);
        else setLiveCourses(data || []);
      });
  }, [user?.id]);

  const filtered = liveCourses.filter(c =>
    c.name.toLowerCase().includes(filter.toLowerCase()) ||
    c.code.toLowerCase().includes(filter.toLowerCase())
  );

  const course = liveCourses.find(c => c.id === selected);
  const courseFiles = course?.files || [];
  const courseDeadlines = course?.deadlines || (course?.tasks || []).map((task) => ({
    label: task.due_at ? new Date(task.due_at).toLocaleString("uk-UA") : "Без дедлайну",
    urgent: task.due_at ? new Date(task.due_at) < new Date() : false,
    title: task.title,
    points: null,
    progress: null,
  }));

  const handleDeleteCourse = async (courseToDelete) => {
    if (!window.confirm(`Видалити курс «${courseToDelete.name}»?`)) return;

    if (supabase) {
      const { error } = await coursesApi.remove(courseToDelete.id);
      if (error) {
        setSyncError(`Не вдалося видалити курс: ${error.message}`);
        return;
      }
    }

    setLiveCourses((items) => items.filter((item) => item.id !== courseToDelete.id));
    setSelected(null);
  };

  const connectMoodle = async () => {
    setSyncStatus("syncing");
    setSyncError("");
    const { data, error } = await moodleApi.sync(moodleUrl.trim(), moodleToken.trim());
    if (error || data?.error) {
      setSyncError(error?.message || data.error);
      setSyncStatus("error");
      return;
    }
    const { data: refreshedCourses } = await supabase.from("courses").select("*, tasks(*)").eq("user_id", user.id).order("name");
    setLiveCourses(refreshedCourses || []);
    setSyncStatus("done");
    setMoodleToken("");
    setMoodleModal(false);
  };

  return (
    <div className="flex flex-col w-full p-8 max-w-7xl mx-auto space-y-8">

      {/* Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div>
          <div className="text-[11px] uppercase tracking-wider text-gray-500 flex items-center gap-2 mb-1">
            <span className="material-symbols-outlined" style={{ fontSize: 14 }}>folder</span>
            Усі дисципліни / Семестр IV
          </div>
          <h1 className="text-[28px] font-semibold tracking-tight">Мої курси</h1>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <span className="material-symbols-outlined absolute left-3 top-2.5 text-gray-400" style={{ fontSize: 18 }}>search</span>
            <input
              className="w-full pl-9 pr-4 py-2 bg-gray-100 dark:bg-gray-900 rounded-xl border border-gray-200 dark:border-gray-800 text-[14px] placeholder:text-gray-400 outline-none focus:border-gray-400 transition-colors"
              placeholder="Фільтрувати курси..."
              value={filter}
              onChange={e => setFilter(e.target.value)}
            />
          </div>
          <button
            onClick={() => setMoodleModal(true)}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 text-[12px] font-medium hover:opacity-90 transition-opacity whitespace-nowrap shadow-sm"
          >
            <span className="material-symbols-outlined" style={{ fontSize: 18 }}>link</span>
            Підключити Moodle
          </button>
        </div>
      </div>

      {/* Course Grid or Detail */}
      {!selected ? (
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
          {syncError && <div className="md:col-span-2 rounded-xl bg-red-50 p-4 text-sm text-red-700">{syncError}</div>}
          {!filtered.length && <div className="md:col-span-2 rounded-xl border border-dashed border-gray-300 bg-white p-10 text-center text-sm text-gray-500">Курсів ще немає. Підключіть Moodle, щоб завантажити актуальні курси.</div>}
          {filtered.map(c => (
            <div
              key={c.id}
              onClick={() => setSelected(c.id)}
              className="group cursor-pointer bg-white dark:bg-gray-900 rounded-xl p-6 border border-gray-200 dark:border-gray-800 hover:border-gray-400 transition-all duration-200 flex flex-col justify-between relative overflow-hidden"
            >
              <div className={`absolute top-0 right-0 w-32 h-32 rounded-full blur-2xl pointer-events-none transition-all ${c.glow}`} />
              <div>
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <span className={`w-3 h-3 rounded-full ${c.color}`} />
                    <span className="text-[11px] text-gray-500 uppercase tracking-wider">{c.code}</span>
                  </div>
                  <span className="text-[11px] px-2.5 py-1 rounded-full bg-gray-100 dark:bg-gray-800 text-gray-500">{c.source === "moodle" ? "Moodle" : "Ручний курс"}</span>
                </div>
                <h3 className={`text-[20px] font-semibold mb-2 transition-colors ${c.hoverText}`}>{c.name}</h3>
                <p className="text-[13px] text-gray-500 mb-4">{c.teacher ? `Викладач: ${c.teacher}` : c.source === "moodle" ? "Дані завантажені з Moodle" : "Створено вручну"}</p>
              </div>
              <div className="pt-4 border-t border-gray-100 dark:border-gray-800 flex items-center justify-between text-[13px] text-gray-500">
                <div className="flex items-center gap-4">
                  <span className="flex items-center gap-1.5">
                    <span className="material-symbols-outlined" style={{ fontSize: 16 }}>assignment</span>
                    {c.tasks?.length ?? c.task_count ?? 0} завдань
                  </span>
                  <span className="flex items-center gap-1.5">
                    <span className="material-symbols-outlined" style={{ fontSize: 16 }}>description</span>
                    {c.materials ?? 0} матеріалів
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <button type="button" onClick={(event) => { event.stopPropagation(); handleDeleteCourse(c); }} className="flex items-center gap-1 rounded-md px-2 py-1 text-[11px] font-medium text-gray-400 hover:bg-red-50 hover:text-red-600">
                    <span className="material-symbols-outlined" style={{ fontSize: 15 }}>delete</span>
                    Видалити
                  </button>
                  <span className="material-symbols-outlined text-gray-400 group-hover:translate-x-1 transition-transform">arrow_forward</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        /* Detail View */
        <div className="bg-white dark:bg-gray-900 rounded-xl p-8 border border-gray-200 dark:border-gray-800 space-y-6">
          <div className="flex items-center justify-between pb-6 border-b border-gray-100 dark:border-gray-800">
            <div className="flex items-center gap-3">
              <button
                onClick={() => setSelected(null)}
                className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-gray-500"
              >
                <span className="material-symbols-outlined">arrow_back</span>
              </button>
              <div>
                <div className="flex items-center gap-2">
                  <span className={`w-2.5 h-2.5 rounded-full ${course.color}`} />
                  <span className="text-[11px] text-gray-500 uppercase tracking-wider">{course.code}</span>
                </div>
                <h2 className="text-[28px] font-semibold">{course.name}</h2>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button type="button" onClick={() => handleDeleteCourse(course)} className="rounded-lg px-3 py-1.5 text-[12px] font-medium text-red-600 transition-colors hover:bg-red-50">Видалити курс</button>
              <button type="button" className="flex items-center gap-1.5 rounded-lg bg-gray-100 px-3 py-1.5 text-[12px] font-medium transition-colors hover:bg-gray-200 dark:bg-gray-800 dark:hover:bg-gray-700">
                <span className="material-symbols-outlined" style={{ fontSize: 16 }}>sync</span>
                Оновити з Moodle
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Materials */}
            <div className="lg:col-span-2 space-y-6">
              <h3 className="text-[16px] font-semibold flex items-center gap-2">
                <span className="material-symbols-outlined text-gray-400" style={{ fontSize: 18 }}>menu_book</span>
                Останні матеріали з Moodle
              </h3>
              <div className="space-y-2">
                {courseFiles.length ? courseFiles.map((f, i) => (
                  <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-gray-50 dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
                    <div className="flex items-center gap-3">
                      <span className={`material-symbols-outlined ${f.color}`}>{f.icon}</span>
                      <div>
                        <div className="text-[14px] font-medium">{f.title}</div>
                        <div className="text-[11px] text-gray-500">{f.meta}</div>
                      </div>
                    </div>
                    <button className="text-[12px] font-medium hover:underline">{f.action}</button>
                  </div>
                )) : <p className="rounded-lg bg-gray-50 p-4 text-sm text-gray-500">Матеріалів Moodle ще не повернув.</p>}
              </div>
            </div>

            {/* Deadlines */}
            <div className="space-y-4">
              <h3 className="text-[16px] font-semibold flex items-center gap-2">
                <span className="material-symbols-outlined text-orange-400" style={{ fontSize: 18 }}>event</span>
                Дедлайни по курсу
              </h3>
              <div className="space-y-3">
                {courseDeadlines.length ? courseDeadlines.map((d, i) => (
                  <div key={i} className="p-4 rounded-xl border border-gray-200 dark:border-gray-700 space-y-2">
                    <div className="flex items-center justify-between">
                      <span className={`text-[11px] px-2 py-0.5 rounded font-medium ${d.urgent ? "bg-red-100 text-red-700" : "bg-gray-100 dark:bg-gray-800 text-gray-500"}`}>
                        {d.label}
                      </span>
                      {d.points != null && <span className="text-[11px] text-gray-500">{d.points} балів</span>}
                    </div>
                    <div className="text-[14px] font-medium">{d.title}</div>
                    {d.progress !== null && (
                      <div className="w-full bg-gray-200 dark:bg-gray-700 h-1.5 rounded-full overflow-hidden">
                        <div className="bg-orange-400 h-full rounded-full" style={{ width: `${d.progress}%` }} />
                      </div>
                    )}
                  </div>
                )) : <p className="rounded-lg bg-gray-50 p-4 text-sm text-gray-500">Дедлайнів Moodle ще не повернув.</p>}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Moodle Modal */}
      {moodleModal && (
        <div
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4"
          onClick={() => setMoodleModal(false)}
        >
          <div
            className="bg-white dark:bg-gray-900 rounded-xl p-6 max-w-md w-full border border-gray-200 dark:border-gray-800 space-y-4 shadow-xl"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex items-center justify-between">
              <h3 className="text-[20px] font-semibold">Підключення Moodle</h3>
              <button onClick={() => setMoodleModal(false)} className="p-1 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-400">
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>
            <p className="text-[13px] text-gray-500">
              Введіть адресу вашого університетського Moodle та токен доступу для автоматичної синхронізації матеріалів і дедлайнів.
            </p>
            <div className="space-y-3">
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">URL Moodle</label>
                <input
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400"
                  placeholder="https://moodle.university.edu.ua"
                  value={moodleUrl}
                  onChange={e => setMoodleUrl(e.target.value)}
                />
              </div>
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">Токен веб-сервісу</label>
                <input
                  type="password"
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400"
                  placeholder="••••••••••••••••"
                  value={moodleToken}
                  onChange={e => setMoodleToken(e.target.value)}
                />
              </div>
            </div>
            <div className="flex justify-end gap-2 pt-2">
              <button
                onClick={connectMoodle}
                disabled={syncStatus === "syncing" || !moodleUrl || !moodleToken}
                className="px-4 py-2 rounded-xl bg-gray-100 dark:bg-gray-800 text-[12px] font-medium hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
              >
                Скасувати
              </button>
              <button
                onClick={() => setMoodleModal(false)}
                className="px-4 py-2 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 text-[12px] font-medium hover:opacity-90 transition-opacity"
              >
                {syncStatus === "syncing" ? "Перевірка..." : "З’єднати"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { supabase } from "./supabase.js";

function requireSupabase() {
  if (!supabase) {
    throw new Error("Supabase is not configured. Add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY.");
  }

  return supabase;
}

const getGoogleRedirectUrl = () => {
  const origin = window.location.origin;
  if (origin.includes("localhost")) {
    return "http://localhost:5173";
  }
  return origin;
};

export const authApi = {
  signInWithGoogle: () => requireSupabase().auth.signInWithOAuth({
    provider: "google",
    options: {
      redirectTo: `${getGoogleRedirectUrl()}/auth/callback`,
    },
  }),
  signIn: (email, password) => requireSupabase().auth.signInWithPassword({ email, password }),
  signUp: (email, password, fullName) => requireSupabase().auth.signUp({
    email,
    password,
    options: { data: { full_name: fullName } },
  }),
  resetPassword: (email) => requireSupabase().auth.resetPasswordForEmail(email),
  signOut: () => requireSupabase().auth.signOut(),
};

export const coursesApi = {
  list: () => requireSupabase().from("courses").select("*").order("name"),
  create: (course) => requireSupabase().from("courses").insert(course).select().single(),
  update: (id, changes) => requireSupabase().from("courses").update(changes).eq("id", id).select().single(),
  remove: (id) => requireSupabase().from("courses").delete().eq("id", id),
};

export const tasksApi = {
  list: () => requireSupabase().from("tasks").select("*, courses(name, color)").order("due_at"),
  create: (task) => requireSupabase().from("tasks").insert(task).select().single(),
  update: (id, changes) => requireSupabase().from("tasks").update(changes).eq("id", id).select().single(),
  remove: (id) => requireSupabase().from("tasks").delete().eq("id", id),
};

export const moodleApi = {
  sync: (baseUrl, token) => requireSupabase().functions.invoke("moodle-sync", {
    body: { baseUrl, token },
  }),
};

export const adminApi = {
  overview: async () => {
    const client = requireSupabase();
    const [profiles, courses, tasks, moodleConnections] = await Promise.all([
      client.from("profiles").select("id, full_name, role, created_at").order("created_at", { ascending: false }),
      client.from("courses").select("id, name, source, user_id").order("created_at", { ascending: false }),
      client.from("tasks").select("id, title, source, completed_at").order("created_at", { ascending: false }),
      client.from("moodle_connections").select("id, base_url, last_synced_at").order("connected_at", { ascending: false }),
    ]);
    const requestError = profiles.error || courses.error || tasks.error || moodleConnections.error;

    return {
      data: requestError ? null : {
        profiles: profiles.data || [],
        courses: courses.data || [],
        tasks: tasks.data || [],
        moodle_connections: moodleConnections.data || [],
      },
      error: requestError,
    };
  },
};

