    glow: "bg-amber-700/5 group-hover:bg-amber-700/10",
    hoverText: "group-hover:text-amber-700",
    tasks: 2,
    materials: 9,
    status: "Синхронізовано",
    deadlines: [
      { label: "Сьогодні, 23:59", urgent: true, title: "Реалізація міграцій БД", points: 15, progress: 90 },
    ],
