            <p className="text-[13px] text-gray-500">
              Введіть адресу вашого університетського Moodle та токен доступу для автоматичної синхронізації матеріалів і дедлайнів.
            </p>
            <div className="space-y-3">
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">URL Moodle</label>
                <input
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400"
                  placeholder="https://moodle.university.edu.ua"
