              <div>
                <label className="text-[11px] text-gray-500 block mb-1">Токен веб-сервісу</label>
                <input
                  type="password"
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400"
                  placeholder="••••••••••••••••"
                  value={moodleToken}
                  onChange={e => setMoodleToken(e.target.value)}
                />
              </div>
            </div>
            <div className="flex justify-end gap-2 pt-2">
              <button
