            <div className="flex items-center justify-between">
              <h3 className="text-[20px] font-semibold">Підключення Moodle</h3>
              <button onClick={() => setMoodleModal(false)} className="p-1 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-400">
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>
            <p className="text-[13px] text-gray-500">
              Введіть дані для підключення до університетського Moodle. Токен веб-сервісу не потрібен.
            </p>
            <div className="space-y-3">
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">URL Moodle</label>
                <input
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400"
                  placeholder="https://moodle.uzhnu.edu.ua"
                  value={moodleUrl}
                  onChange={e => setMoodleUrl(e.target.value)}
                />
              </div>
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">MoodleSession cookie</label>
                <input
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400 font-mono"
                  placeholder="iqcst2rm71682ae1p1agm58m5v"
                  value={moodleSession}
                  onChange={e => setMoodleSession(e.target.value)}
                />
                <p className="text-[11px] text-gray-400 mt-1">F12 → Application → Cookies → MoodleSession</p>
              </div>
              <div>
                <label className="text-[11px] text-gray-500 block mb-1">Sesskey</label>
                <input
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 text-[14px] outline-none focus:border-gray-400 font-mono"
                  placeholder="D4rPf4zteb"
                  value={sesskey}
                  onChange={e => setSesskey(e.target.value)}
                />
                <p className="text-[11px] text-gray-400 mt-1">F12 → Console → window.M?.cfg?.sesskey</p>
              </div>
            </div>
            {syncStatus === "error" && syncError && (
              <p className="text-[12px] text-red-600 bg-red-50 rounded-lg px-3 py-2">{syncError}</p>
            )}
            <div className="flex justify-end gap-2 pt-2">
              <button
                onClick={() => setMoodleModal(false)}
                className="px-4 py-2 rounded-xl bg-gray-100 dark:bg-gray-800 text-[12px] font-medium hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
              >
                Скасувати
              </button>
              <button
                onClick={connectMoodle}
                disabled={syncStatus === "syncing" || !moodleUrl || !moodleSession || !sesskey}
                className="px-4 py-2 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 text-[12px] font-medium hover:opacity-90 transition-opacity disabled:opacity-50"
              >
                {syncStatus === "syncing" ? "Перевірка..." : "З'єднати"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

