  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) {
    return json({ error: "Invalid session" }, 401);
  }

  const body = await request.json().catch(() => ({}));
  const { moodleUrl, moodleSession, sesskey, action, courseid } = body;

  if (!moodleUrl || !moodleSession || !sesskey) {
    return json({ error: "moodleUrl, moodleSession і sesskey обов'язкові" }, 400);
  }

  const baseUrl = String(moodleUrl).replace(/\/$/, "");
  const cookie = `MoodleSession=${moodleSession}`;

  // Формуємо тіло запиту до Moodle AJAX API
  let ajaxBody: Array<{ index: number; methodname: string; args: Record<string, unknown> }> = [];

  if (action === "connect" || action === "test" || action === "courses") {
    ajaxBody = [{
      index: 0,
      methodname: "core_course_get_enrolled_courses_by_timeline_classification",
      args: { offset: 0, limit: 0, classification: "all", sort: "fullname" },
    }];
  } else if (action === "deadlines") {
    ajaxBody = [{
      index: 0,
      methodname: "core_calendar_get_action_events_by_timesort",
      args: {
        timesortfrom: Math.floor(Date.now() / 1000),
        timesortto: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 30, // наступні 30 днів
        limitnum: 50,
      },
    }];
  } else if (action === "grades") {
    ajaxBody = [{
      index: 0,
      methodname: "gradereport_overview_get_course_grades",
      args: { userid: 0 },
    }];
  } else {
    return json({ error: `Невідома дія: ${action}` }, 400);
  }

  // Запит до Moodle через cookie-авторизацію
  let moodleData: unknown;
  try {
    const response = await fetch(`${baseUrl}/lib/ajax/service.php?sesskey=${sesskey}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Cookie": cookie,
      },
      body: JSON.stringify(ajaxBody),
    });

    if (!response.ok) {
      return json({ error: `Moodle повернув статус ${response.status}` }, 502);
    }

    moodleData = await response.json();
  } catch (err) {
    return json({ error: err instanceof Error ? err.message : "Не вдалося зв'язатись з Moodle" }, 502);
  }

  // Перевіряємо чи Moodle не повернув помилку (наприклад, невалідний sesskey)
  const firstItem = Array.isArray(moodleData) ? moodleData[0] : null;
  if (firstItem?.error) {
    return json({ error: firstItem.error }, 400);
  }

  // Для дії "connect" — зберігаємо з'єднання та синхронізуємо курси
  if (action === "connect") {
    // Зберігаємо moodle_session і sesskey у БД
    const { error: upsertError } = await supabase.from("moodle_connections").upsert({
      user_id: user.id,
      base_url: baseUrl,
      moodle_session: moodleSession,
      sesskey: sesskey,
      connected_at: new Date().toISOString(),
      last_synced_at: new Date().toISOString(),
    }, { onConflict: "user_id" });

    if (upsertError) {
      return json({ error: upsertError.message }, 500);
    }

    // Синхронізуємо курси якщо Moodle їх повернув
    const rawCourses = firstItem?.data ?? [];
    if (Array.isArray(rawCourses)) {
      for (const course of rawCourses as Array<{ id: number; fullname?: string; shortname?: string }>) {
        await supabase.from("courses").upsert({
          user_id: user.id,
          name: course.fullname ?? course.shortname ?? `Course ${course.id}`,
          color: "gray",
          source: "moodle",
          external_id: String(course.id),
        }, { onConflict: "user_id,source,external_id" });
      }
    }

    return json({
      ok: true,
      courses: Array.isArray(rawCourses) ? rawCourses.length : 0,
    });
  }

  // Для решти дій — повертаємо сирі дані з Moodle
  return json(moodleData);
});

