  setSyncStatus("syncing");
  setSyncError("");
  const { data, error } = await moodleProxyApi.connect(
    moodleUrl.trim(),
    moodleSession.trim(),
    sesskey.trim()
  );

  if (error) {
    // Витягуємо читабельний текст з FunctionsHttpError
    let msg = error.message ?? "Помилка з'єднання";
    try {
      const body = await error.context?.json?.();
      if (body?.error) msg = body.error;
    } catch { /* ігноруємо */ }
    setSyncError(msg);
    setSyncStatus("error");
    return;
  }

  if (data?.error) {
    setSyncError(data.error);
    setSyncStatus("error");
    return;
  }

  const { data: refreshedCourses } = await supabase.from("courses").select("*, tasks(*)").eq("user_id", user.id).order("name");
  setLiveCourses(refreshedCourses || []);
  setSyncStatus("done");
  setMoodleSession("");
  setSesskey("");
  setMoodleModal(false);
};

