import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

// ── Типи ─────────────────────────────────────────────────────────────────────

interface MoodleCourse {
  id: number;
  fullname?: string;
  shortname?: string;
}

interface MoodleModule {
  id: number;
  name: string;
  modname: string;       // 'assign', 'resource', 'url', 'quiz', 'forum', etc.
  modplural?: string;
  url?: string;
  description?: string;
  dates?: Array<{ label: string; timestamp: number }>;
  duedate?: number;
}

interface MoodleSection {
  id: number;
  name: string;
  section: number;
  modules: MoodleModule[];
}

interface MoodleAssignment {
  id: number;
  name: string;
  duedate?: number;
  intro?: string;
  course?: number;
}

// ── Утиліти ───────────────────────────────────────────────────────────────────

/** Надсилає запит до Moodle AJAX API */
async function callMoodleAjax(
  baseUrl: string,
  sesskey: string,
  cookie: string,
  methodname: string,
  args: Record<string, unknown>,
): Promise<unknown> {
  const body = [{ index: 0, methodname, args }];
  const res = await fetch(`${baseUrl}/lib/ajax/service.php?sesskey=${sesskey}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "Cookie": cookie },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`Moodle HTTP ${res.status}`);
  const data = await res.json();
  const item = Array.isArray(data) ? data[0] : null;
  if (item?.error) throw new Error(String(item.error));
  return item?.data;
}

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (request.method !== "POST") {
    return json({ error: "Only POST is supported" }, 405);
  }

  const authorization = request.headers.get("Authorization");
  if (!authorization) return json({ error: "Authorization header is required" }, 401);

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authorization } } },
  );

  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) return json({ error: "Invalid session" }, 401);

  const body = await request.json().catch(() => ({}));
  const { moodleUrl, moodleSession, sesskey, action, courseId } = body;

  if (!moodleUrl || !moodleSession || !sesskey) {
    return json({ error: "moodleUrl, moodleSession і sesskey обов'язкові" }, 400);
  }

  const baseUrl = String(moodleUrl).replace(/\/$/, "");
  const cookie = `MoodleSession=${moodleSession}`;

  // ── Дія: connect ─────────────────────────────────────────────────────────────
  // Перевіряє сесію, зберігає з'єднання, синхронізує список курсів
  if (action === "connect" || action === "test" || action === "courses") {
    let rawData: unknown;
    try {
      rawData = await callMoodleAjax(baseUrl, sesskey, cookie,
        "core_course_get_enrolled_courses_by_timeline_classification",
        { offset: 0, limit: 0, classification: "all", sort: "fullname" },
      );
    } catch (err) {
      return json({ error: err instanceof Error ? err.message : "Moodle недоступний" }, 502);
    }

    // Структура: { courses: [...] } або просто [...]
    const rawCourses: MoodleCourse[] = Array.isArray(rawData)
      ? rawData
      : Array.isArray((rawData as { courses?: MoodleCourse[] })?.courses)
        ? (rawData as { courses: MoodleCourse[] }).courses
        : [];

    if (action === "connect") {
      // Зберігаємо з'єднання
      const { error: upsertErr } = await supabase.from("moodle_connections").upsert({
        user_id: user.id,
        base_url: baseUrl,
        moodle_session: moodleSession,
        sesskey,
        connected_at: new Date().toISOString(),
        last_synced_at: new Date().toISOString(),
      }, { onConflict: "user_id" });
      if (upsertErr) return json({ error: upsertErr.message }, 500);

      // Зберігаємо курси
      for (const c of rawCourses) {
        await supabase.from("courses").upsert({
          user_id: user.id,
          name: c.fullname ?? c.shortname ?? `Course ${c.id}`,
          color: "gray",
          source: "moodle",
          external_id: String(c.id),
        }, { onConflict: "user_id,source,external_id" });
      }

      return json({ ok: true, courses: rawCourses.length });
    }

    return json({ ok: true, courses: rawCourses });
  }

  // ── Дія: sync_course_content ──────────────────────────────────────────────
  // Синхронізує всі модулі курсу (секції + завдання) в course_materials і tasks
  if (action === "sync_course_content") {
    if (!courseId) return json({ error: "courseId обов'язковий для sync_course_content" }, 400);

    const moodleCourseId = String(courseId);

    // Знаходимо наш внутрішній course.id
    const { data: courseRow, error: courseErr } = await supabase
      .from("courses")
      .select("id")
      .eq("user_id", user.id)
      .eq("external_id", moodleCourseId)
      .maybeSingle();

    if (courseErr) return json({ error: courseErr.message }, 500);
    if (!courseRow) return json({ error: "Курс не знайдено в БД" }, 404);

    const internalCourseId: string = courseRow.id;

    // 1. Отримуємо всі секції та модулі курсу
    let sections: MoodleSection[] = [];
    try {
      const data = await callMoodleAjax(baseUrl, sesskey, cookie,
        "core_course_get_contents",
        { courseid: Number(moodleCourseId) },
      );
      sections = Array.isArray(data) ? data as MoodleSection[] : [];
    } catch (err) {
      return json({ error: `Не вдалось отримати зміст курсу: ${err instanceof Error ? err.message : err}` }, 502);
    }

    // 2. Отримуємо завдання курсу (з дедлайнами)
    let assignments: MoodleAssignment[] = [];
    try {
      const data = await callMoodleAjax(baseUrl, sesskey, cookie,
        "mod_assign_get_assignments",
        { "courseids[0]": Number(moodleCourseId) },
      ) as { courses?: Array<{ assignments?: MoodleAssignment[] }> };
      assignments = data?.courses?.[0]?.assignments ?? [];
    } catch {
      // Якщо немає завдань — не критично, продовжуємо
      assignments = [];
    }

    // Індекс дедлайнів по id завдання
    const deadlineMap = new Map<number, number>();
    for (const a of assignments) {
      if (a.duedate && a.duedate > 0) deadlineMap.set(a.id, a.duedate);
    }

    // 3. Зберігаємо всі модулі в course_materials
    let materialsCount = 0;
    let tasksCount = 0;

    for (const section of sections) {
      const sectionName = section.name || `Секція ${section.section}`;
      const sectionNum = section.section;

      for (const mod of (section.modules ?? [])) {
        // Пропускаємо порожні label-и без назви
        if (mod.modname === "label" && !mod.name?.trim()) continue;

        const dueTimestamp = deadlineMap.get(mod.id);
        const dueAt = dueTimestamp ? new Date(dueTimestamp * 1000).toISOString() : null;

        // Зберігаємо в course_materials
        await supabase.from("course_materials").upsert({
          user_id: user.id,
          course_id: internalCourseId,
          module_type: mod.modname,
          title: mod.name,
          description: mod.description ?? null,
          url: mod.url ?? null,
          due_at: dueAt,
          section_name: sectionName,
          section_num: sectionNum,
          external_id: String(mod.id),
          external_course_id: moodleCourseId,
        }, { onConflict: "user_id,external_id" });

        materialsCount++;

        // Завдання і тести також дублюємо в tasks (для дедлайнів і прогресу)
        if (mod.modname === "assign" || mod.modname === "quiz") {
          await supabase.from("tasks").upsert({
            user_id: user.id,
            course_id: internalCourseId,
            title: mod.name,
            description: mod.description ?? null,
            due_at: dueAt,
            source: "moodle",
            external_id: `moodle-${mod.id}`,
          }, { onConflict: "user_id,source,external_id" });

          tasksCount++;
        }
      }
    }

    // Оновлюємо last_synced_at
    await supabase.from("moodle_connections")
      .update({ last_synced_at: new Date().toISOString() })
      .eq("user_id", user.id);

    return json({
      ok: true,
      courseId: internalCourseId,
      materials: materialsCount,
      tasks: tasksCount,
      sections: sections.length,
    });
  }

  // ── Дія: deadlines ────────────────────────────────────────────────────────
  if (action === "deadlines") {
    try {
      const data = await callMoodleAjax(baseUrl, sesskey, cookie,
        "core_calendar_get_action_events_by_timesort",
        {
          timesortfrom: Math.floor(Date.now() / 1000),
          timesortto: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 30,
          limitnum: 50,
        },
      );
      return json(data);
    } catch (err) {
      return json({ error: err instanceof Error ? err.message : "Помилка" }, 502);
    }
  }

  // ── Дія: grades ───────────────────────────────────────────────────────────
  if (action === "grades") {
    try {
      const data = await callMoodleAjax(baseUrl, sesskey, cookie,
        "gradereport_overview_get_course_grades",
        { userid: 0 },
      );
      return json(data);
    } catch (err) {
      return json({ error: err instanceof Error ? err.message : "Помилка" }, 502);
    }
  }

  return json({ error: `Невідома дія: ${action}` }, 400);
});

