input.newStr:
// ── Дія: sync_course_content ──────────────────────────────────────────────
if (action === "sync_course_content") {
  if (!courseId) return json({ error: "courseId обов'язковий для sync_course_content" }, 400);

  const moodleCourseId = String(courseId);

  const { data: courseRow, error: courseErr } = await supabase
    .from("courses")
    .select("id")
    .eq("user_id", user.id)
    .eq("external_id", moodleCourseId)
    .maybeSingle();

  if (courseErr) return json({ error: courseErr.message }, 500);
  if (!courseRow) return json({ error: "Курс не знайдено в БД" }, 404);

  const internalCourseId: string = courseRow.id;

  // Паралельно отримуємо секції і завдання
  const [sectionsResult, assignmentsResult] = await Promise.allSettled([
    callMoodleAjax(baseUrl, sesskey, cookie,
      "core_course_get_contents",
      { courseid: Number(moodleCourseId) },
    ),
    callMoodleAjax(baseUrl, sesskey, cookie,
      "mod_assign_get_assignments",
      { "courseids[0]": Number(moodleCourseId) },
    ),
  ]);

  if (sectionsResult.status === "rejected") {
    return json({ error: `Не вдалось отримати зміст курсу: ${sectionsResult.reason}` }, 502);
  }

  const sections: MoodleSection[] = Array.isArray(sectionsResult.value)
    ? sectionsResult.value as MoodleSection[]
    : [];

  // Будуємо map дедлайнів assign_id → timestamp
  const deadlineMap = new Map<number, number>();
  if (assignmentsResult.status === "fulfilled") {
    const aData = assignmentsResult.value as { courses?: Array<{ assignments?: MoodleAssignment[] }> };
    for (const a of aData?.courses?.[0]?.assignments ?? []) {
      if (a.duedate && a.duedate > 0) deadlineMap.set(a.id, a.duedate);
    }
  }

  // Збираємо всі матеріали в масиви для batch upsert
  const materialsRows: Record<string, unknown>[] = [];
  const tasksRows: Record<string, unknown>[] = [];

  for (const section of sections) {
    const sectionName = section.name || `Секція ${section.section}`;
    const sectionNum  = section.section;

    for (const mod of (section.modules ?? [])) {
      if (mod.modname === "label" && !mod.name?.trim()) continue;

      const dueTimestamp = deadlineMap.get(mod.id);
      const dueAt = dueTimestamp ? new Date(dueTimestamp * 1000).toISOString() : null;

      materialsRows.push({
        user_id:            user.id,
        course_id:          internalCourseId,
        module_type:        mod.modname,
        title:              mod.name,
        description:        mod.description ?? null,
        url:                mod.url ?? null,
        due_at:             dueAt,
        section_name:       sectionName,
        section_num:        sectionNum,
        external_id:        String(mod.id),
        external_course_id: moodleCourseId,
      });

      if (mod.modname === "assign" || mod.modname === "quiz") {
        tasksRows.push({
          user_id:     user.id,
          course_id:   internalCourseId,
          title:       mod.name,
          description: mod.description ?? null,
          due_at:      dueAt,
          source:      "moodle",
          external_id: `moodle-${mod.id}`,
        });
      }
    }
  }

  // Batch upsert по 50 рядків за раз
  const chunkSize = 50;
  for (let i = 0; i < materialsRows.length; i += chunkSize) {
    const { error: mErr } = await supabase.from("course_materials")
      .upsert(materialsRows.slice(i, i + chunkSize), { onConflict: "user_id,external_id" });
    if (mErr) return json({ error: `course_materials: ${mErr.message}` }, 500);
  }

  for (let i = 0; i < tasksRows.length; i += chunkSize) {
    const { error: tErr } = await supabase.from("tasks")
      .upsert(tasksRows.slice(i, i + chunkSize), { onConflict: "user_id,source,external_id" });
    if (tErr) return json({ error: `tasks: ${tErr.message}` }, 500);
  }

  await supabase.from("moodle_connections")
    .update({ last_synced_at: new Date().toISOString() })
    .eq("user_id", user.id);

  return json({
    ok: true,
    materials: materialsRows.length,
    tasks: tasksRows.length,
    sections: sections.length,
  });
}

