/** Надсилає запит до Moodle AJAX API */
async function callMoodleAjax(
  baseUrl: string,
  sesskey: string,
  cookie: string,
  methodname: string,
  args: Record<string, unknown>,
): Promise<unknown> {
  const body = [{ index: 0, methodname, args }];

  // Таймаут 20 секунд щоб не зависати
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20_000);

  let res: Response;
  try {
    res = await fetch(`${baseUrl}/lib/ajax/service.php?sesskey=${sesskey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Cookie": cookie },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (err) {
    clearTimeout(timeout);
    const msg = err instanceof Error ? err.message : String(err);
    throw new Error(msg.includes("aborted") ? "Moodle не відповів за 20 секунд (можливо сесія протухла)" : msg);
  } finally {
    clearTimeout(timeout);
  }

  if (!res.ok) throw new Error(`Moodle HTTP ${res.status}`);

  // Перевіряємо Content-Type — якщо HTML значить редирект на логін (сесія протухла)
  const contentType = res.headers.get("content-type") ?? "";
  if (contentType.includes("text/html")) {
    throw new Error("Moodle повернув HTML замість JSON — MoodleSession протухла, оновіть підключення");
  }

  const data = await res.json();
  const item = Array.isArray(data) ? data[0] : null;
  if (item?.error) throw new Error(String(item.error));
  return item?.data;
}

