/** Отримує актуальний sesskey через MoodleSession cookie — парсить головну сторінку */
async function fetchSesskey(baseUrl: string, cookie: string): Promise<string | null> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15_000);
  try {
    const res = await fetch(`${baseUrl}/my/`, {
      headers: { "Cookie": cookie },
      redirect: "follow",
      signal: controller.signal,
    });
    if (!res.ok) return null;
    const html = await res.text();

    // Варіант 1: sesskey в data-attribute або JSON конфігу
    const match =
      html.match(/"sesskey"\s*:\s*"([a-zA-Z0-9]+)"/) ||
      html.match(/sesskey=([a-zA-Z0-9]+)/) ||
      html.match(/"sesskey":"([a-zA-Z0-9]+)"/);

    return match?.[1] ?? null;
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

