Deno.serve(async (request) => {
  if (request.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (request.method !== "POST") {
    return json({ error: "Only POST is supported" }, 405);
  }

  // Авторизація
  const authorization = request.headers.get("Authorization");
  if (!authorization) {
    return json({ error: "Authorization header is required" }, 401);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authorization } } },
  );

  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) {
    return json({ error: "Invalid session" }, 401);
  }

  // Парсимо тіло
  const body = await request.json().catch(() => ({}));
  const { moodleUrl, moodleSession, sesskey, action, courseId } = body;

  if (!moodleUrl || !moodleSession) {
    return json({ error: "moodleUrl і moodleSession обов'язкові" }, 400);
  }

  const baseUrl = String(moodleUrl).replace(/\/$/, "");
  const cookie  = `MoodleSession=${moodleSession}`;

  // Отримуємо свіжий sesskey автоматично
  const freshSesskey = await fetchSesskey(baseUrl, cookie);
  const activeSesskey = freshSesskey ?? String(sesskey ?? "");

  if (!activeSesskey) {
    return json({ error: "MoodleSession протухла — підключіть Moodle знову на сторінці Курси" }, 401);
  }

  // Якщо sesskey оновився — зберігаємо в БД (fire-and-forget)
  if (freshSesskey && freshSesskey !== sesskey) {
    supabase.from("moodle_connections")
      .update({ sesskey: freshSesskey })
      .eq("user_id", user.id)
      .then(() => {});
  }

  try {
    // ── connect / courses ───────────────────────────────────────────────────
    if (action === "connect" || action === "test" || action === "courses") {
      const rawData = await callMoodleAjax(baseUrl, activeSesskey, cookie,
        "core_course_get_enrolled_courses_by_timeline_classification",
        { offset: 0, limit: 0, classification: "all", sort: "fullname" },
      );

      const rawCourses: MoodleCourse[] = Array.isArray(rawData)
        ? rawData as MoodleCourse[]
        : Array.isArray((rawData as { courses?: MoodleCourse[] })?.courses)
          ? (rawData as { courses: MoodleCourse[] }).courses
          : [];

      if (action === "connect") {
        const { error: upsertErr } = await supabase.from("moodle_connections").upsert({
          user_id:        user.id,
          base_url:       baseUrl,
          moodle_session: moodleSession,
          sesskey:        activeSesskey,
          connected_at:   new Date().toISOString(),
          last_synced_at: new Date().toISOString(),
        }, { onConflict: "user_id" });
        if (upsertErr) return json({ error: upsertErr.message }, 500);

        for (const c of rawCourses) {
          await supabase.from("courses").upsert({
            user_id:     user.id,
            name:        c.fullname ?? c.shortname ?? `Course ${c.id}`,
            color:       "gray",
            source:      "moodle",
            external_id: String(c.id),
          }, { onConflict: "user_id,source,external_id" });
        }

        return json({ ok: true, courses: rawCourses.length });
      }

      return json({ ok: true, courses: rawCourses });
    }

    // ── sync_course_content ─────────────────────────────────────────────────
    if (action === "sync_course_content") {
      if (!courseId) return json({ error: "courseId обов'язковий" }, 400);

      const moodleCourseId = String(courseId);

      const { data: courseRow, error: courseErr } = await supabase
        .from("courses")
        .select("id")
        .eq("user_id", user.id)
        .eq("external_id", moodleCourseId)
        .maybeSingle();

      if (courseErr) return json({ error: courseErr.message }, 500);
      if (!courseRow) return json({ error: "Курс не знайдено в БД" }, 404);

      const internalCourseId: string = courseRow.id;

      // Паралельно: секції курсу + завдання з дедлайнами
      const [sectionsResult, assignmentsResult] = await Promise.allSettled([
        callMoodleAjax(baseUrl, activeSesskey, cookie,
          "core_course_get_contents",
          { courseid: Number(moodleCourseId) },
        ),
        callMoodleAjax(baseUrl, activeSesskey, cookie,
          "mod_assign_get_assignments",
          { "courseids[0]": Number(moodleCourseId) },
        ),
      ]);

      if (sectionsResult.status === "rejected") {
        return json({ error: `Не вдалось отримати зміст курсу: ${sectionsResult.reason}` }, 502);
      }

      const sections: MoodleSection[] = Array.isArray(sectionsResult.value)
        ? sectionsResult.value as MoodleSection[]
        : [];

      // Map: module_id → duedate
      const deadlineMap = new Map<number, number>();
      if (assignmentsResult.status === "fulfilled") {
        const aData = assignmentsResult.value as { courses?: Array<{ assignments?: MoodleAssignment[] }> };
        for (const a of aData?.courses?.[0]?.assignments ?? []) {
          if (a.duedate && a.duedate > 0) deadlineMap.set(a.id, a.duedate);
        }
      }

      // Збираємо рядки для batch upsert
      const materialsRows: Record<string, unknown>[] = [];
      const tasksRows:     Record<string, unknown>[] = [];

      for (const section of sections) {
        const sectionName = section.name || `Секція ${section.section}`;
        const sectionNum  = section.section;

        for (const mod of section.modules ?? []) {
          if (mod.modname === "label" && !mod.name?.trim()) continue;

          const dueTs = deadlineMap.get(mod.id);
          const dueAt = dueTs ? new Date(dueTs * 1000).toISOString() : null;

          materialsRows.push({
            user_id:            user.id,
            course_id:          internalCourseId,
            module_type:        mod.modname,
            title:              mod.name,
            description:        mod.description ?? null,
            url:                mod.url ?? null,
            due_at:             dueAt,
            section_name:       sectionName,
            section_num:        sectionNum,
            external_id:        String(mod.id),
            external_course_id: moodleCourseId,
          });

          if (mod.modname === "assign" || mod.modname === "quiz") {
            tasksRows.push({
              user_id:     user.id,
              course_id:   internalCourseId,
              title:       mod.name,
              description: mod.description ?? null,
              due_at:      dueAt,
              source:      "moodle",
              external_id: `moodle-${mod.id}`,
            });
          }
        }
      }

      // Batch upsert по 50
      const CHUNK = 50;
      for (let i = 0; i < materialsRows.length; i += CHUNK) {
        const { error: e } = await supabase.from("course_materials")
          .upsert(materialsRows.slice(i, i + CHUNK), { onConflict: "user_id,external_id" });
        if (e) return json({ error: `course_materials: ${e.message}` }, 500);
      }
      for (let i = 0; i < tasksRows.length; i += CHUNK) {
        const { error: e } = await supabase.from("tasks")
          .upsert(tasksRows.slice(i, i + CHUNK), { onConflict: "user_id,source,external_id" });
        if (e) return json({ error: `tasks: ${e.message}` }, 500);
      }

      await supabase.from("moodle_connections")
        .update({ last_synced_at: new Date().toISOString() })
        .eq("user_id", user.id);

      return json({ ok: true, materials: materialsRows.length, tasks: tasksRows.length, sections: sections.length });
    }

    // ── deadlines ───────────────────────────────────────────────────────────
    if (action === "deadlines") {
      const data = await callMoodleAjax(baseUrl, activeSesskey, cookie,
        "core_calendar_get_action_events_by_timesort",
        {
          timesortfrom: Math.floor(Date.now() / 1000),
          timesortto:   Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 30,
          limitnum:     50,
        },
      );
      return json(data);
    }

    // ── grades ──────────────────────────────────────────────────────────────
    if (action === "grades") {
      const data = await callMoodleAjax(baseUrl, activeSesskey, cookie,
        "gradereport_overview_get_course_grades",
        { userid: 0 },
      );
      return json(data);
    }

    return json({ error: `Невідома дія: ${action}` }, 400);

  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error("moodle-proxy error:", msg);
    return json({ error: msg }, 500);
  }
});

