// ── sync_course_content ─────────────────────────────────────────────────
if (action === "sync_course_content") {
  // Отримуємо всі події з календаря на 6 місяців вперед
  const calendarData = await callMoodleAjax(baseUrl, activeSesskey, cookie,
    "core_calendar_get_action_events_by_timesort",
    {
      timesortfrom: Math.floor(Date.now() / 1000) - 60 * 60 * 24 * 30, // 30 днів назад
      timesortto:   Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 180, // 6 місяців вперед
      limitnum:     200,
    },
  ) as { events?: Array<{
    id: number;
    name: string;
    description?: string;
    timestart?: number;
    course?: { id: number; fullname?: string };
    modulename?: string;
    url?: string;
  }> };

  const events = calendarData?.events ?? [];

  // Завантажуємо всі Moodle курси юзера з БД
  const { data: userCourses } = await supabase
    .from("courses")
    .select("id, external_id")
    .eq("user_id", user.id)
    .eq("source", "moodle");

  const courseMap = new Map<string, string>(); // external_id → internal uuid
  for (const c of userCourses ?? []) {
    if (c.external_id) courseMap.set(c.external_id, c.id);
  }

  const tasksRows: Record<string, unknown>[] = [];

  for (const event of events) {
    const moodleCourseId = String(event.course?.id ?? "");
    const internalCourseId = courseMap.get(moodleCourseId);
    if (!internalCourseId) continue; // подія не відноситься до відомого курсу

    const dueAt = event.timestart
      ? new Date(event.timestart * 1000).toISOString()
      : null;

    tasksRows.push({
      user_id:     user.id,
      course_id:   internalCourseId,
      title:       event.name,
      description: event.description
        ? event.description.replace(/<[^>]*>/g, "").trim().slice(0, 1000) || null
        : null,
      due_at:      dueAt,
      source:      "moodle",
      external_id: `moodle-cal-${event.id}`,
    });
  }

  // Batch upsert
  const CHUNK = 50;
  for (let i = 0; i < tasksRows.length; i += CHUNK) {
    const { error: e } = await supabase.from("tasks")
      .upsert(tasksRows.slice(i, i + CHUNK), { onConflict: "user_id,source,external_id" });
    if (e) return json({ error: `tasks: ${e.message}` }, 500);
  }

  await supabase.from("moodle_connections")
    .update({ last_synced_at: new Date().toISOString() })
    .eq("user_id", user.id);

  return json({ ok: true, tasks: tasksRows.length, events: events.length });
}

